CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.gn_networks (id text PRIMARY KEY, ssid text NOT NULL, bssid text NOT NULL UNIQUE, venue text NOT NULL DEFAULT '', added_at bigint NOT NULL);
GRANT SELECT ON public.gn_networks TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.gn_networks TO authenticated;
GRANT ALL ON public.gn_networks TO service_role;
ALTER TABLE public.gn_networks ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_pool ON public.gn_networks FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY admin_pool ON public.gn_networks FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gn_sessions (id text PRIMARY KEY, user_id uuid NOT NULL, payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.gn_sessions TO authenticated;
GRANT ALL ON public.gn_sessions TO service_role;
ALTER TABLE public.gn_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_or_admin_sessions ON public.gn_sessions FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gn_transactions (id text PRIMARY KEY, user_id uuid NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.gn_transactions TO authenticated;
GRANT ALL ON public.gn_transactions TO service_role;
ALTER TABLE public.gn_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_or_admin_payments ON public.gn_transactions FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gn_settings (id text PRIMARY KEY DEFAULT 'global', apk_url text NOT NULL DEFAULT '', latest_version text NOT NULL DEFAULT '1.0.0', update_required boolean NOT NULL DEFAULT false, live boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.gn_settings TO anon;
GRANT SELECT,INSERT,UPDATE ON public.gn_settings TO authenticated;
GRANT ALL ON public.gn_settings TO service_role;
ALTER TABLE public.gn_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.gn_settings FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY admin_settings ON public.gn_settings FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.gn_payment_credentials (id text PRIMARY KEY DEFAULT 'global', api_token text NOT NULL DEFAULT '', username text NOT NULL DEFAULT '', password text NOT NULL DEFAULT '', channel_id text NOT NULL DEFAULT '');
GRANT ALL ON public.gn_payment_credentials TO service_role;
ALTER TABLE public.gn_payment_credentials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.gn_mesh_links (id text PRIMARY KEY, user_id uuid NOT NULL, payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.gn_mesh_links TO authenticated;
GRANT ALL ON public.gn_mesh_links TO service_role;
ALTER TABLE public.gn_mesh_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_mesh_write ON public.gn_mesh_links FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY admin_mesh_read ON public.gn_mesh_links FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.gn_networks,public.gn_sessions,public.gn_transactions,public.gn_settings,public.gn_mesh_links;